#!/usr/bin/env node
// Writes the two reference pages of the `envy` agent skill from the code that
// already defines them, so a new setting or a re-bound key can never leave the
// documentation lying:
//
//   agents/skills/envy/settings.md   <- config/schema.json
//   agents/skills/envy/shortcuts.md  <- src/shortcut-specs.ts (SHORTCUT_SPECS)
//
//   node scripts/gen-skill-docs.mjs           # write both files
//   node scripts/gen-skill-docs.mjs --check   # fail if either is stale
//
// The generated files are committed, so the skill works from a checkout and
// from the installed package without a build step. `--check` runs in
// scripts/check.sh.

import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath, pathToFileURL } from 'node:url'

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..')
const outDir = path.join(root, 'agents', 'skills', 'envy')

const check = process.argv.includes('--check')
if (process.argv.slice(2).some((a) => a !== '--check')) {
  console.error('usage: node scripts/gen-skill-docs.mjs [--check]')
  process.exit(2)
}

// --- helpers ------------------------------------------------------------------

const BANNER = (source) =>
  `<!-- Generated by scripts/gen-skill-docs.mjs from ${source}. Do not edit by hand. -->\n`

/// A markdown table cell: pipes would end the cell and newlines would end the
/// row, so both are neutralised.
const cell = (s) => String(s).replace(/\|/g, '\\|').replace(/\s*\n\s*/g, ' ').trim()

const code = (s) => '`' + s + '`'

/// TOML literal for a default value, as it would be typed into the fence.
function tomlValue(v) {
  if (typeof v === 'string') return `"${v}"`
  return String(v)
}

/// The map value types read as bare nouns in the schema; give them an article
/// so the generated sentence is a sentence.
const VALUE_TYPE_PROSE = {
  chord: 'a chord, spelled the way `shortcuts.md` describes',
  color: 'a color',
  emoji: 'an emoji',
}

function typeCell(key) {
  if (key.type === 'theme') {
    return 'one of `omarchy`, `system`, `dark`, `light`, or a theme file name'
  }
  if (Array.isArray(key.values)) {
    const list = key.values.map((v) => code(tomlValue(v))).join(', ')
    if (key.min !== undefined || key.max !== undefined) {
      return `number, any value from ${key.min} to ${key.max}; Settings offers ${list}`
    }
    return `one of ${list}`
  }
  if (key.type === 'int' || key.type === 'number') {
    const range =
      key.min !== undefined || key.max !== undefined
        ? ` from ${key.min ?? '-inf'} to ${key.max ?? 'inf'}`
        : ''
    return `${key.type}${range}`
  }
  return key.type
}

function meaningCell(key) {
  const parts = []
  parts.push(key.doc?.trim() || `${key.label}.`)
  if (key.owner === 'rust') parts.push('Read by Rust at startup, before the window opens.')
  return cell(parts.join(' '))
}

// --- settings.md --------------------------------------------------------------

function renderSettings(schema) {
  const out = []
  out.push(BANNER('config/schema.json'))
  out.push('# Envy settings reference\n')
  out.push(
    `Every key of the toml fence in ${code(schema.file)}. A key that is not in the`,
    'file keeps its default. An unknown key or a bad value is reported by',
    '`envynote config check` and ignored by the app; it never stops Envy',
    'starting.\n',
  )
  out.push('Top-level keys go above the first `[table]` header. Everything else')
  out.push('belongs under the header named in each section below.\n')

  for (const table of schema.tables) {
    const header = table.table ? `\`[${table.table}]\`` : 'Top level (no table header)'
    out.push(`## ${table.title} / ${header}\n`)
    out.push('| Key | Type | Default | What it does |')
    out.push('| --- | --- | --- | --- |')
    for (const key of table.keys) {
      out.push(
        `| ${code(key.key)} | ${typeCell(key)} | ${code(tomlValue(key.default))} | ${meaningCell(key)} |`,
      )
    }
    out.push('')
  }

  out.push('## Maps\n')
  out.push('These tables hold whatever keys you put in them, not a fixed list.\n')
  for (const map of schema.maps) {
    out.push(`### ${map.title} / \`[${map.table}]\`\n`)
    out.push(`Each value is ${VALUE_TYPE_PROSE[map.value_type] ?? map.value_type}. ${map.doc}\n`)
  }

  out.push('## Themes\n')
  out.push(
    `Colors are not settings. \`appearance.theme\` picks a theme and a theme file in`,
    `${code(schema.themes_dir)} defines one. See \`theming.md\`.\n`,
  )

  out.push('## Worked examples\n')
  out.push('Make the note list as dense as it goes. `compact` is the tightest of the')
  out.push('three row heights and it is already the default, so the rest of the work is')
  out.push('turning off the things that add lines and columns:\n')
  out.push('```toml')
  out.push('[list]')
  out.push('density = "compact"')
  out.push('show_preview = false')
  out.push('show_date = false')
  out.push('bold_text = false')
  out.push('```\n')
  out.push('The other direction is `density = "comfy"` with `show_preview = true`.\n')
  out.push('Point Envy at another folder of notes and index its subfolders:\n')
  out.push('```toml')
  out.push('vault = "~/Notes"')
  out.push('')
  out.push('[index]')
  out.push('include_subfolders = true')
  out.push('```\n')
  out.push('Color two tags and give a domain an emoji:\n')
  out.push('```toml')
  out.push('[tag_colors]')
  out.push('work = "#7aa2f7"')
  out.push('reading = "#9ece6a"')
  out.push('')
  out.push('[domain_emojis]')
  out.push('"github.com" = "🐙"')
  out.push('```\n')
  out.push('Bigger interface text and a fixed light theme:\n')
  out.push('```toml')
  out.push('[appearance]')
  out.push('theme = "light"')
  out.push('text_size = 1.15')
  out.push('```\n')
  out.push('After any edit, run `envynote config check`. A running Envy picks the')
  out.push('change up on its own.')

  return out.join('\n').replace(/\n{3,}/g, '\n\n').trimEnd() + '\n'
}

// --- shortcuts.md -------------------------------------------------------------

function renderShortcuts(specs) {
  const out = []
  out.push(BANNER('src/shortcut-specs.ts (SHORTCUT_SPECS)'))
  out.push('# Envy shortcuts reference\n')
  out.push('Every id below can be re-bound in the `[shortcuts]` table of')
  out.push('`~/.config/envy/config.md`:\n')
  out.push('```toml')
  out.push('[shortcuts]')
  out.push('jumpToSearch = "Ctrl+K"')
  out.push('```\n')
  out.push('An id you leave out keeps its default. An id that is not in this list is')
  out.push('reported by `envynote config check` and ignored.\n')

  out.push('## Chord grammar\n')
  out.push('A chord is modifiers then one key, joined by `+`, with no spaces. The')
  out.push('modifier order is fixed: `Ctrl`, then `Alt`, then `Shift`. Write them in')
  out.push('that order or the chord will never match, because Envy compares the')
  out.push('canonical string built by `eventToBinding` in `src/shortcuts.ts`.\n')
  out.push('The key itself is the browser `KeyboardEvent.key` name:\n')
  out.push('- A single letter is upper-cased, so `Ctrl+B`, never `Ctrl+b`. Shift is a')
  out.push('  separate part, so bold with Shift is `Ctrl+Shift+B`.')
  out.push('- Digits and punctuation are the character itself: `Ctrl+0`, `Ctrl+,`,')
  out.push('  `Ctrl+/`, `Ctrl+=`, `Ctrl+-`.')
  out.push('- Named keys keep their `KeyboardEvent.key` spelling: `Enter`, `Escape`,')
  out.push('  `Tab`, `Backspace`, `Delete`, `Home`, `End`, `PageUp`, `PageDown`,')
  out.push('  `ArrowUp`, `ArrowDown`, `ArrowLeft`, `ArrowRight`, `F1` to `F12`.')
  out.push('- The space bar is written `Space`.\n')
  out.push('There is no `Meta` or `Super` modifier. Envy never builds one, so a chord')
  out.push('containing it can never match, and the Super key belongs to the compositor')
  out.push('anyway. For a Super chord, add a Hyprland bind instead.\n')
  out.push('Write the long arrow names in the file. Envy shortens them to `Down`,')
  out.push('`Up`, `Left` and `Right` for display only, so `Ctrl+Alt+Down` in the file')
  out.push('is a chord that can never fire.\n')
  out.push('Two actions bound to the same chord is a conflict: only one of them can')
  out.push('ever run, and Envy flags it in Settings. Check the table before picking a')
  out.push('chord.\n')

  const rows = (list) =>
    [
      '| Id | What it does | Default chord |',
      '| --- | --- | --- |',
      ...list.map((s) => `| ${code(s.id)} | ${cell(s.label)} | ${code(s.default)} |`),
    ].join('\n')

  const globals = specs.filter((s) => s.global)
  const editor = specs.filter((s) => s.editor && !s.global)
  const rest = specs.filter((s) => !s.global && !s.editor)

  out.push('## Global shortcuts\n')
  out.push('These are meant to work from any app. On Wayland no app can register a')
  out.push('global hotkey, so on Omarchy and Hyprland the chord in the config file is')
  out.push('not what fires them: a Hyprland bind is. `linux/hyprland-envy.lua` binds')
  out.push('`CTRL + ALT + RETURN` to `envy-summon.sh`, which runs `envynote --toggle`')
  out.push('over the control socket. That file is loaded by one line in')
  out.push('`~/.config/hypr/bindings.lua`, which `system.hyprland_bind = true` in')
  out.push('config.md adds (and `false` removes) — see settings.md. To change the')
  out.push('summon chord, edit the Hyprland bind (see the `omarchy` skill) and not')
  out.push('this table. The entries here still matter on X11 and for a future portal')
  out.push('backend.\n')
  out.push(rows(globals) + '\n')

  out.push('## Editor shortcuts\n')
  out.push('Handled inside the editor, so they only fire while the note has focus.\n')
  out.push(rows(editor) + '\n')

  out.push('## Window shortcuts\n')
  out.push('Handled by the window, so they fire wherever focus is inside Envy.\n')
  out.push(rows(rest) + '\n')

  out.push('## Worked example\n')
  out.push('Move Jump to Search onto Ctrl+K and put the layout toggle on F6:\n')
  out.push('```toml')
  out.push('[shortcuts]')
  out.push('jumpToSearch = "Ctrl+K"')
  out.push('toggleLayout = "F6"')
  out.push('```\n')
  out.push('Then `envynote config check`. The change applies to the running app.')

  return out.join('\n').replace(/\n{3,}/g, '\n\n').trimEnd() + '\n'
}

// --- run ----------------------------------------------------------------------

const schema = JSON.parse(fs.readFileSync(path.join(root, 'config', 'schema.json'), 'utf8'))

// The table is pure data in its own module, so Node can import it directly.
const { SHORTCUT_SPECS } = await import(pathToFileURL(path.join(root, 'src', 'shortcut-specs.ts')))

const files = [
  { name: 'settings.md', content: renderSettings(schema) },
  { name: 'shortcuts.md', content: renderShortcuts(SHORTCUT_SPECS) },
]

/// First line that differs, so a stale file says what changed rather than just
/// that something did.
function firstDifference(expected, actual) {
  const a = actual.split('\n')
  const b = expected.split('\n')
  const show = (line) => (line === undefined ? '(end of file)' : line === '' ? '(blank line)' : line)
  for (let i = 0; i < Math.max(a.length, b.length); i++) {
    if (a[i] !== b[i]) {
      return [`  line ${i + 1}:`, `  - ${show(a[i])}`, `  + ${show(b[i])}`].join('\n')
    }
  }
  return ''
}

let stale = 0
for (const file of files) {
  const target = path.join(outDir, file.name)
  const actual = fs.existsSync(target) ? fs.readFileSync(target, 'utf8') : null

  if (check) {
    if (actual === file.content) continue
    stale++
    const rel = path.relative(root, target)
    if (actual === null) {
      console.error(`stale: ${rel} does not exist`)
    } else {
      console.error(`stale: ${rel}`)
      console.error(`--- ${rel}`)
      console.error(`+++ generated from the source`)
      console.error(firstDifference(file.content, actual))
    }
    continue
  }

  if (actual === file.content) {
    console.log(`unchanged  ${path.relative(root, target)}`)
    continue
  }
  fs.mkdirSync(outDir, { recursive: true })
  fs.writeFileSync(target, file.content)
  console.log(`wrote      ${path.relative(root, target)}`)
}

if (check && stale) {
  console.error('\nRun `node scripts/gen-skill-docs.mjs` and commit the result.')
  process.exit(1)
}
